  'BOZOLLOK': 'data:image/png;base64,',
  'BUCK': 'data:image/png;base64,',
  'CODEMAX': 'data:image/png;base64,',
  'CORVIDA': 'data:image/png;base64,',
  'DRONE': 'data:image/png;base64,',
  'DUPLAIRE': 'data:image/png;base64,',
  'EXOR': 'data:image/png;base64,',
  'GOLGAR': 'data:image/png;base64,',
